# External fixture registrations are frozen BEFORE branch construction.
from dataclasses import dataclass

@dataclass(frozen=True)
class ExternalRegistration:
    branch_id: str
    fixture_digest: str
    prefix_json: str
    source_pins_json: str
    registration_digest: str

def register_fixture(fixture,branch_id,source_pins):
    from .stfbs_d1b_qm_scenario import validate_fixture
    from .stfbs_d1b_qm_execution import IDENTITIES
    from .stfbs_d1a_replay import digest
    validate_fixture(fixture)
    if branch_id not in IDENTITIES or not source_pins:raise ValueError('External registration identity/pins required')
    prefix=json.dumps({h['target_id']:h for h in fixture.view['histories']},sort_keys=True)
    payload=dict(branch_id=branch_id,fixture_digest=digest(dict(view=fixture.view,seed=fixture.seed,world=fixture.world,identity=fixture.identity)),prefix_json=prefix,source_pins_json=json.dumps(source_pins,sort_keys=True))
    return ExternalRegistration(**payload,registration_digest=digest(payload))

def verify_registration(registration,fixture,branch_id):
    if type(registration) is not ExternalRegistration:raise ValueError('External registration required')
    expected=register_fixture(fixture,branch_id,json.loads(registration.source_pins_json))
    if expected!=registration:raise ValueError('Fixture/prefix/branch registration mismatch')
    return True

def audit_registered(branch,registration):
    from .stfbs_d1a_history_audit import AuditContext,audit_branch_independent
    from .stfbs_d1a_replay import digest
    if type(registration) is not ExternalRegistration:raise ValueError('External registration required')
    payload={k:getattr(registration,k) for k in ('branch_id','fixture_digest','prefix_json','source_pins_json')}
    if digest(payload)!=registration.registration_digest or branch.name!=registration.branch_id:raise ValueError('External identity mismatch')
    # Never reads branch._audit_context; frozen prefix supplied by external registration.
    return audit_branch_independent(branch,context=AuditContext(registration.branch_id,registration.prefix_json))

# RUN-G0 scientific evidence joins: only reads existing schema fields.
@dataclass(frozen=True)
class SourceAnchor:
    source_version: str
    expected_json: str

@dataclass(frozen=True)
class VerifiedRegistration:
    registration: object
    anchor: SourceAnchor

def verify_source_pins(root,provided,anchor):
    if type(anchor) is not SourceAnchor or not anchor.source_version:raise ValueError('EXTERNAL_SOURCE_ANCHOR_REQUIRED')
    root=Path(root).resolve();expected=json.loads(anchor.expected_json)
    if provided!=expected or not expected:raise ValueError('SOURCE_ANCHOR_MISMATCH')
    results=[]
    for name,want in expected.items():
        path=Path(name)
        if path.is_absolute() or '..' in path.parts or path.as_posix()!=name or ':' in name:raise ValueError('SOURCE_PATH_REJECTED')
        target=(root/path).resolve()
        if not target.is_relative_to(root) or not target.is_file():raise ValueError('SOURCE_FILE_MISSING_OR_OUTSIDE_ROOT')
        actual=sha(target)
        if actual!=want:raise ValueError('SOURCE_BYTES_MISMATCH: '+name)
        results.append(dict(path=name,actual_sha256=actual,expected_sha256=want,bytes=target.stat().st_size,source_version=anchor.source_version,checked_utc=time.time(),match=True))
    return results

def register_verified_fixture(root,fixture,branch_id,provided,anchor):
    from .stfbs_d1b_qm_independent_audit import register_fixture
    verify_source_pins(root,provided,anchor)
    return VerifiedRegistration(register_fixture(fixture,branch_id,provided),anchor)

def verify_verified_registration(root,fixture,branch_id,verified):
    from .stfbs_d1b_qm_independent_audit import verify_registration
    if type(verified) is not VerifiedRegistration:raise ValueError('VERIFIED_EXTERNAL_REGISTRATION_REQUIRED')
    verify_source_pins(root,json.loads(verified.registration.source_pins_json),verified.anchor)
    verify_registration(verified.registration,fixture,branch_id)
    return verified.registration

class EndpointEvidenceError(ValueError):pass

def endpoint_join(endpoint,records,registration,*,segment_id=None,side=None):
    """The caller supplies an independently frozen external registration, not endpoint fields."""
    from .stfbs_d1a_replay import digest
    from research.information_service_online.public import seal_slot
    from research.information_service.public_quality import prepare_frame
    branch=registration.expected_branch_id if hasattr(registration,'expected_branch_id') else registration.branch_id
    def reject(detail):raise EndpointEvidenceError('ENDPOINT_PROVENANCE_MISMATCH: '+detail)
    if endpoint['branch']!=branch or endpoint['observation_origin']!='MODEL' or endpoint['provenance']!='SIMULATED':reject('external branch/source')
    # quality.frame_id is an existing scientific field supplied by the real processor.
    fid=endpoint['quality']['frame_id']
    candidates=[]
    for row in records['feedback']:
        frame=row['frame'];result=row['result']
        if frame['frame_id']==fid and result['frame_id']==fid:
            candidates.append(row)
    if len(candidates)!=1:reject('fusion link is missing or ambiguous')
    row=candidates[0];frame=row['frame'];result=row['result']
    if row['endpoint']!=endpoint:reject('feedback endpoint scientific identity conflict')
    if not frame['stream_id'].startswith(branch+':T'+str(endpoint['target_id'])+':first') or frame['frame_id']!=frame['stream_id']+':tick'+str(endpoint['tick']):reject('frame/stream scientific identity')
    if result['stream_id']!=frame['stream_id'] or result['target_id']!=endpoint['target_id'] or result['tick']!=endpoint['tick'] or result['quality']!=endpoint['quality']:reject('fusion result/quality')
    if frame['tick']!=endpoint['tick'] or frame['target_id']!=endpoint['target_id']:reject('frame target/time')
    segments=[s for s in records['histories'][endpoint['target_id']]['segments'] if s['team']==endpoint['team'] and s['start_tick']<=endpoint['tick'] and (s['closure'] is None or s['closure']['at']['time_seconds']>=endpoint['tick']*.05)]
    if segment_id is not None:segments=[s for s in segments if s['segment_id']==segment_id]
    if len(segments)!=1:reject('service segment ambiguity')
    segment=segments[0]
    if segment['model_branch_id']!=branch:reject('segment branch')
    if side=='LEFT' and segment['start_tick']!=endpoint['tick']:reject('left endpoint outside opening transaction')
    if side=='RIGHT' and segment['start_tick']>=endpoint['tick']:reject('right endpoint before first interval')
    # Feedback order must agree with old-right then new-left for equal tick.
    index=records['feedback'].index(row)
    for earlier in records['feedback'][:index]:
        if earlier['endpoint']['tick']>endpoint['tick']:reject('fusion event order')
        if side=='RIGHT' and earlier['endpoint']['tick']==endpoint['tick'] and earlier['endpoint']['team']!=endpoint['team']:reject('right after competing left')
    expected_sensors=['U'+str(m['robot_id']) for m in endpoint['team']]
    clean=prepare_frame(frame,expected_sensors)
    for field in ('payload','payload_sha256','frame_sha256','normalized_frame'):
        if result[field]!=clean[field]:reject('normalized WLS input '+field)
    if len(row['slots'])!=len(endpoint['team']):reject('slot/team cardinality')
    for member,slot in zip(endpoint['team'],row['slots']):
        robot=member['robot_id'];key=(branch,endpoint['target_id'],robot,endpoint['tick'])
        if key not in records['cache']:reject('raw key scientific identity')
        raw=records['cache'][key]
        if seal_slot(slot)!=slot or raw['slot']!=slot or raw['slot_digest']!=digest(slot):reject('slot/raw content')
        physical=records['physical_profiles'][endpoint['tick']][robot]
        context=dict(position=records['positions'][endpoint['tick']][robot],sigma=physical['sigma'],health=physical['health'])
        if raw['context_digest']!=digest(context):reject('raw context')
        found=[x for x in frame['records'] if x['sensor_id']=='U'+str(robot)]
        if slot['state']=='MISSING':
            if slot['packet'] is not None or found or physical['health']=='available':reject('missing semantics')
        elif slot['state']=='VALID':
            if len(found)!=1 or physical['health']!='available':reject('valid semantics')
            packet=deepcopy(found[0]);packet_id=packet.pop('packet_id')
            if packet!=slot['packet'] or packet['sigma']!=physical['sigma'] or packet['position']!=context['position']:reject('packet/frame/physical sigma')
            if packet_id!=frame['stream_id']+':tick'+str(endpoint['tick'])+':U'+str(robot):reject('frame packet identity')
        else:reject('unqueried endpoint slot')
    return dict(status='PASS',branch=branch,target_id=endpoint['target_id'],tick=endpoint['tick'],segment_id=segment['segment_id'],stream_id=frame['stream_id'],frame_id=fid,feedback_index=index,side=side,endpoint_digest=digest(endpoint),source='READ_ONLY_CROSS_RECORD_JOIN')
